def minSpreadTriple(a, b, c):
    i = j = k = 0
    best = None
    while i < len(a) and j < len(b) and k < len(c):
        x, y, z = a[i], b[j], c[k]
        lo, hi = min(x, y, z), max(x, y, z)
        if best is None or hi - lo < best:
            best = hi - lo
        if best == 0:
            break
        if x == lo:
            i += 1
        elif y == lo:
            j += 1
        else:
            k += 1
    return best
